import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"Analytics Journey Tracker — enumerated source for the Analytics Journey Tracker assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/analytics-journey-question-set.md","filePath":"frameworks/analytics-journey-question-set.md"}'),n={name:"frameworks/analytics-journey-question-set.md"};function o(s,t,i,c,l,u){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="analytics-journey-tracker-—-enumerated-source-for-the-analytics-journey-tracker-assessment" tabindex="-1">Analytics Journey Tracker — enumerated source for the Analytics Journey Tracker assessment <a class="header-anchor" href="#analytics-journey-tracker-—-enumerated-source-for-the-analytics-journey-tracker-assessment" aria-label="Permalink to &quot;Analytics Journey Tracker — enumerated source for the Analytics Journey Tracker assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>analytics.journey.yaml</code> scores the data and analytics capabilities Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/c7c36e71-70a1-463d-a0c9-2155692f9fca/" target="_blank" rel="noreferrer">Analytics Journey Tracker</a> evaluates. The tracker is a data strategy accelerator: it measures capabilities and processes across several pillars at five maturity levels, then helps build use cases, initiatives and a roadmap. This page lists the items Scout asks, and every rule in that file cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/c7c36e71-70a1-463d-a0c9-2155692f9fca/" target="_blank" rel="noreferrer">Analytics Journey Tracker</a> (90 minutes, multiple choice and multiple response; question text and pillar names not published)</td></tr><tr><td>Framework version</td><td>Cloud Adoption Framework unified data platform scenario (planning, architecture, data governance, Fabric governance, operational standards) and the Microsoft Fabric adoption roadmap with its maturity levels, current on Microsoft Learn at the extraction date. Not versioned by Microsoft</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The assessment landing page, the CAF unified data platform overview, planning, architecture, data governance, Fabric governance and operational standards pages, the Fabric adoption roadmap maturity-levels page and the CAF cloud-scale analytics URL were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. The Fabric adoption roadmap data culture, executive sponsorship and overview pages and the Microsoft Purview data governance overview were read through <code>microsoft_docs_search</code> excerpts the same day. Every <code>collect.json</code> property an automated item reads was checked against the header contract in <code>src/collect/Invoke-Collect.ps1</code>.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list, and the pillars are not Microsoft&#39;s.</strong> The tracker&#39;s landing page names five maturity levels, <strong>Initial</strong> (non-existent, unpredictable, reactive), <strong>Evolving</strong> (frequently reactive, ad hoc), <strong>Acceptable</strong> (well characterised, more proactive than reactive), <strong>Advanced</strong> (measured and controlled, predictable) and <strong>Optimized</strong> (stable, flexible, fed back through improvement loops), but it does not name its pillars or publish its questions. The seven areas below, and the <code>ANLJT-*</code> IDs, are <strong>Scout&#39;s</strong> grouping of the published guidance.</p><p>Scout does not assign a maturity level. Each item is a practice the guidance describes, written so it can be answered Yes, Partial or No; Yes and No sit near the Acceptable-or-better and Initial-or-Evolving ends of the five levels. The score is the share of items met.</p><p>The Cloud Adoption Framework&#39;s former cloud-scale analytics scenario no longer exists: its URL now serves the <strong>Unified data platform</strong> guidance, which is the source used here, together with the Fabric adoption roadmap&#39;s maturity-level topics. Microsoft has also stopped creating new Microsoft Purview data governance accounts and is consolidating data governance into Fabric, so Purview accounts are attached as evidence and never required.</p><p>Sources:</p><ul><li>[OV] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/data/executive-strategy-unified-data-platform" target="_blank" rel="noreferrer">Unified data platform adoption</a></li><li>[PLAN] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/data/planning-unified-data-platform" target="_blank" rel="noreferrer">Planning for a unified data platform</a></li><li>[ARCH] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/data/architecture-unified-data-platform" target="_blank" rel="noreferrer">Architecture for a unified data platform</a></li><li>[DG] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/data/data-governance-unified-data-platform" target="_blank" rel="noreferrer">Data governance in a unified data platform</a></li><li>[FG] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/data/fabric-governance-unified-data-platform" target="_blank" rel="noreferrer">Fabric governance in a unified data platform</a></li><li>[OPS] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/data/operational-standards-unified-data-platform" target="_blank" rel="noreferrer">Operational standards for a unified data platform</a></li><li>[FAR] <a href="https://learn.microsoft.com/power-bi/guidance/fabric-adoption-roadmap" target="_blank" rel="noreferrer">Microsoft Fabric adoption roadmap</a></li><li>[FML] <a href="https://learn.microsoft.com/power-bi/guidance/fabric-adoption-roadmap-maturity-levels" target="_blank" rel="noreferrer">Microsoft Fabric adoption roadmap maturity levels</a></li><li>[FDC] <a href="https://learn.microsoft.com/power-bi/guidance/fabric-adoption-roadmap-data-culture" target="_blank" rel="noreferrer">Microsoft Fabric adoption roadmap: Data culture</a></li><li>[FES] <a href="https://learn.microsoft.com/power-bi/guidance/fabric-adoption-roadmap-executive-sponsorship" target="_blank" rel="noreferrer">Microsoft Fabric adoption roadmap: Executive sponsorship</a></li><li>[PUR] <a href="https://learn.microsoft.com/purview/data-governance-overview" target="_blank" rel="noreferrer">Data governance with Microsoft Purview</a></li></ul><h2 id="how-the-items-are-answered" tabindex="-1">How the items are answered <a class="header-anchor" href="#how-the-items-are-answered" aria-label="Permalink to &quot;How the items are answered&quot;">​</a></h2><p>Most items are questions about how the organization works, which no Azure API can read. They are <strong>manual</strong> rules: Scout lists them in <code>assessment-questions.csv</code> (or <code>Export-ScoutAssessmentQuestion</code>), and a person answers <code>Yes</code>, <code>Partial</code>, <code>No</code> or <code>N/A</code>. See <a href="./../assessment/questionnaire-answers.html">Questionnaire answers</a>. Where collected Azure data bears on a question, it is attached to the item as evidence, but the answer still decides the score. Items marked ✅ are <strong>automated</strong> and <strong>gated</strong>: they run only when the resources they read exist (or the data source was collected), so an estate without them reports the item Not assessed, never Passed or Failed, and an answer file cannot override them.</p><h2 id="the-enumeration-—-52-items-across-7-areas" tabindex="-1">The enumeration — 52 items across 7 areas <a class="header-anchor" href="#the-enumeration-—-52-items-across-7-areas" aria-label="Permalink to &quot;The enumeration — 52 items across 7 areas&quot;">​</a></h2><h3 id="strategy-and-business-alignment-anljt-str-—-5-items" tabindex="-1">Strategy and business alignment (ANLJT-STR) — 5 items <a class="header-anchor" href="#strategy-and-business-alignment-anljt-str-—-5-items" aria-label="Permalink to &quot;Strategy and business alignment (ANLJT-STR) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ANLJT-STR-01</td><td>An executive sponsor with enough authority across the organization drives the data and analytics strategy</td><td>❌ Manual</td><td>FES, FML</td></tr><tr><td>ANLJT-STR-02</td><td>Data and analytics goals are aligned to business goals, and each data product supports a defined business outcome</td><td>❌ Manual</td><td>PLAN, FAR</td></tr><tr><td>ANLJT-STR-03</td><td>A prioritized roadmap of data products exists, with an investment case and a fund, defer or reject decision for each proposal</td><td>❌ Manual</td><td>PLAN</td></tr><tr><td>ANLJT-STR-04</td><td>Funded data products are reassessed as priorities change, and those whose value no longer justifies the cost are reduced or retired</td><td>❌ Manual</td><td>PLAN</td></tr><tr><td>ANLJT-STR-05</td><td>A data culture is built deliberately: goals are set to advance informed decision-making and progress is tracked</td><td>❌ Manual</td><td>FDC</td></tr></tbody></table><h3 id="organization-operating-model-and-skills-anljt-org-—-8-items" tabindex="-1">Organization, operating model and skills (ANLJT-ORG) — 8 items <a class="header-anchor" href="#organization-operating-model-and-skills-anljt-org-—-8-items" aria-label="Permalink to &quot;Organization, operating model and skills (ANLJT-ORG) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ANLJT-ORG-01</td><td>A federated operating model combines organization-wide governance with accountable data domains</td><td>❌ Manual</td><td>PLAN</td></tr><tr><td>ANLJT-ORG-02</td><td>Each data domain has one senior owner with the authority to set priorities and resolve competing needs</td><td>❌ Manual</td><td>PLAN</td></tr><tr><td>ANLJT-ORG-03</td><td>Policies and platform guardrails that need consistency are centralized, with a documented exception process</td><td>❌ Manual</td><td>PLAN</td></tr><tr><td>ANLJT-ORG-04</td><td>A Center of Excellence has clear goals and scope and includes representation from every key business unit</td><td>❌ Manual</td><td>FML</td></tr><tr><td>ANLJT-ORG-05</td><td>Staffing follows the data product roadmap, using dedicated, shared or external staff as sustained demand justifies</td><td>❌ Manual</td><td>PLAN</td></tr><tr><td>ANLJT-ORG-06</td><td>Skills gaps are identified from the roadmap and closed with applied training and validated credentials</td><td>❌ Manual</td><td>PLAN</td></tr><tr><td>ANLJT-ORG-07</td><td>A community of practice and a champions network support users, so the community does not rely on a few individuals</td><td>❌ Manual</td><td>FML</td></tr><tr><td>ANLJT-ORG-08</td><td>User support and change management are defined, so changes to solutions and processes do not disrupt or slow users</td><td>❌ Manual</td><td>FAR</td></tr></tbody></table><h3 id="architecture-and-platform-anljt-arc-—-7-items" tabindex="-1">Architecture and platform (ANLJT-ARC) — 7 items <a class="header-anchor" href="#architecture-and-platform-anljt-arc-—-7-items" aria-label="Permalink to &quot;Architecture and platform (ANLJT-ARC) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ANLJT-ARC-01</td><td>The data platform uses the existing Azure landing zone, with data services in workload landing zones, not a separate architecture</td><td>❌ Manual — Microsoft Fabric capacities attached</td><td>ARCH</td></tr><tr><td>ANLJT-ARC-02</td><td>A unified platform for data products (such as Microsoft Fabric with OneLake) is chosen, and existing platforms such as Azure Databricks are kept where they still meet requirements</td><td>❌ Manual — Microsoft Fabric capacities attached</td><td>OV, OPS</td></tr><tr><td>ANLJT-ARC-03</td><td>Fabric capacity is deployed per data domain through its own workload landing zone subscription, in an approved default region</td><td>❌ Manual — Microsoft Fabric capacities attached</td><td>ARCH</td></tr><tr><td>ANLJT-ARC-04</td><td>Source data reaches OneLake with the least movement: shortcuts first, then mirroring, then copying</td><td>❌ Manual</td><td>OPS</td></tr><tr><td>ANLJT-ARC-05</td><td>Operational databases are protected from direct analytical and AI queries unless the database owner has approved the workload</td><td>❌ Manual — SQL servers attached</td><td>OPS</td></tr><tr><td>ANLJT-ARC-06</td><td>A medallion (progressive refinement) pattern is the preferred way to transform data that benefits from it</td><td>❌ Manual — Azure Databricks workspaces attached</td><td>OPS</td></tr><tr><td>ANLJT-ARC-07</td><td>Microsoft Purview, or the governance service you chose, is placed in a workload landing zone and owned centrally, with governance domains aligned to data domains</td><td>❌ Manual — Microsoft Purview accounts attached</td><td>ARCH</td></tr></tbody></table><h3 id="data-governance-and-security-anljt-gov-—-14-items" tabindex="-1">Data governance and security (ANLJT-GOV) — 14 items <a class="header-anchor" href="#data-governance-and-security-anljt-gov-—-14-items" aria-label="Permalink to &quot;Data governance and security (ANLJT-GOV) — 14 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ANLJT-GOV-01</td><td>A data inventory policy defines which data must be discoverable, starting with data behind critical processes, enterprise reporting and AI</td><td>❌ Manual — Microsoft Purview accounts attached</td><td>DG</td></tr><tr><td>ANLJT-GOV-02</td><td>Shared business concepts have an approved definition and an accountable owner, published in a glossary</td><td>❌ Manual</td><td>DG</td></tr><tr><td>ANLJT-GOV-03</td><td>Legal and contractual obligations are turned into data requirements in a central register, and compliance posture is monitored</td><td>❌ Manual</td><td>DG</td></tr><tr><td>ANLJT-GOV-04</td><td>Lineage is captured for important data products to the depth governance decisions need</td><td>❌ Manual</td><td>DG</td></tr><tr><td>ANLJT-GOV-05</td><td>Retention and disposition rules are set per data classification and implemented in Azure data services</td><td>❌ Manual</td><td>DG</td></tr><tr><td>ANLJT-GOV-06</td><td>One classification model and sensitivity-label taxonomy is applied across platforms, and protection is verified across transitions</td><td>❌ Manual</td><td>DG</td></tr><tr><td>ANLJT-GOV-07</td><td>Sensitive data is detected consistently, and data loss prevention covers defined risk scenarios</td><td>❌ Manual</td><td>DG</td></tr><tr><td>ANLJT-GOV-08</td><td>Workspace roles go to Entra security groups, and item and OneLake data access are limited to what each audience needs</td><td>❌ Manual</td><td>FG</td></tr><tr><td>ANLJT-GOV-09</td><td>Fabric inbound and outbound network access follows the organization&#39;s private connectivity standard</td><td>❌ Manual</td><td>FG</td></tr><tr><td>ANLJT-GOV-10</td><td>Azure Data Factory instances do not allow public network access</td><td>✅ Data Factory <code>publicNetworkAccess</code></td><td>DG, FG</td></tr><tr><td>ANLJT-GOV-11</td><td>Azure Data Factory instances have a private endpoint</td><td>✅ Data Factory to private endpoint</td><td>DG, FG</td></tr><tr><td>ANLJT-GOV-12</td><td>Azure Data Factory instances use a managed identity</td><td>✅ Data Factory <code>identityType</code></td><td>DG</td></tr><tr><td>ANLJT-GOV-13</td><td>Azure Synapse workspaces do not allow public network access</td><td>✅ Synapse <code>publicNetworkAccess</code></td><td>DG, FG</td></tr><tr><td>ANLJT-GOV-14</td><td>Azure Synapse workspaces use a managed virtual network</td><td>✅ Synapse managed virtual network</td><td>DG, FG</td></tr></tbody></table><h3 id="data-product-lifecycle-and-operations-anljt-ops-—-8-items" tabindex="-1">Data product lifecycle and operations (ANLJT-OPS) — 8 items <a class="header-anchor" href="#data-product-lifecycle-and-operations-anljt-ops-—-8-items" aria-label="Permalink to &quot;Data product lifecycle and operations (ANLJT-OPS) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ANLJT-OPS-01</td><td>Every published data product has an accountable owner, supported purpose, intended use, access process and quality status</td><td>❌ Manual</td><td>OPS</td></tr><tr><td>ANLJT-OPS-02</td><td>Minimum metadata is defined, so consumers can find the owning domain, owner, supported use and quality commitment</td><td>❌ Manual</td><td>OPS</td></tr><tr><td>ANLJT-OPS-03</td><td>Data products are discoverable in a catalogue and endorsed (promotion, certification) with consistent meanings</td><td>❌ Manual</td><td>OPS</td></tr><tr><td>ANLJT-OPS-04</td><td>The uses each data product supports are defined, and uses that change risk need extra review</td><td>❌ Manual</td><td>OPS</td></tr><tr><td>ANLJT-OPS-05</td><td>Reliability requirements are set per business-criticality tier, and business-critical data products have a tested recovery process</td><td>❌ Manual</td><td>OPS</td></tr><tr><td>ANLJT-OPS-06</td><td>Breaking changes and retirement follow a defined process, with affected consumers identified and a transition period given</td><td>❌ Manual</td><td>OPS</td></tr><tr><td>ANLJT-OPS-07</td><td>Production data products are released through a repeatable process matched to release risk (Git integration, deployment pipelines)</td><td>❌ Manual</td><td>FG</td></tr><tr><td>ANLJT-OPS-08</td><td>Each production data product has a named operational owner, with monitoring and alerting proportionate to its criticality</td><td>❌ Manual</td><td>FG</td></tr></tbody></table><h3 id="cost-management-and-finops-anljt-fin-—-5-items" tabindex="-1">Cost management and FinOps (ANLJT-FIN) — 5 items <a class="header-anchor" href="#cost-management-and-finops-anljt-fin-—-5-items" aria-label="Permalink to &quot;Cost management and FinOps (ANLJT-FIN) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ANLJT-FIN-01</td><td>Cost allocation (showback or chargeback) assigns spend, including shared Fabric capacity, to data domains</td><td>❌ Manual — Microsoft Fabric capacities attached</td><td>PLAN</td></tr><tr><td>ANLJT-FIN-02</td><td>Data domains forecast spend from planned capacity and observed consumption, and update the forecast</td><td>❌ Manual</td><td>PLAN</td></tr><tr><td>ANLJT-FIN-03</td><td>Spending is reviewed against budget and data product value on a regular cadence</td><td>❌ Manual</td><td>PLAN</td></tr><tr><td>ANLJT-FIN-04</td><td>Capacity reservations are bought only once usage is predictable</td><td>❌ Manual — Azure reservations attached</td><td>PLAN</td></tr><tr><td>ANLJT-FIN-05</td><td>Capacity changes follow evidence of sustained demand, changes to shared capacity need approval, and surge protection is used where needed</td><td>❌ Manual</td><td>FG</td></tr></tbody></table><h3 id="adoption-and-value-anljt-val-—-5-items" tabindex="-1">Adoption and value (ANLJT-VAL) — 5 items <a class="header-anchor" href="#adoption-and-value-anljt-val-—-5-items" aria-label="Permalink to &quot;Adoption and value (ANLJT-VAL) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ANLJT-VAL-01</td><td>KPIs or OKRs track data culture goals and the business value of analytics solutions</td><td>❌ Manual</td><td>FDC, FML</td></tr><tr><td>ANLJT-VAL-02</td><td>User adoption is tracked through awareness, understanding, momentum and proficiency, not only usage counts</td><td>❌ Manual</td><td>FML</td></tr><tr><td>ANLJT-VAL-03</td><td>Solutions move through defined adoption phases, with testing, endorsement and clear ownership by the time they are valuable</td><td>❌ Manual</td><td>FML</td></tr><tr><td>ANLJT-VAL-04</td><td>Feedback loops are in place so data products and the data culture keep improving</td><td>❌ Manual</td><td>FDC</td></tr><tr><td>ANLJT-VAL-05</td><td>AI and agent workloads are grounded on governed, trusted data products</td><td>❌ Manual — Azure AI services accounts attached</td><td>OV</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Strategy and business alignment</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Organization, operating model and skills</td><td>8</td><td>0</td><td>8</td></tr><tr><td>Architecture and platform</td><td>7</td><td>0</td><td>7</td></tr><tr><td>Data governance and security</td><td>14</td><td>5</td><td>9</td></tr><tr><td>Data product lifecycle and operations</td><td>8</td><td>0</td><td>8</td></tr><tr><td>Cost management and FinOps</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Adoption and value</td><td>5</td><td>0</td><td>5</td></tr><tr><td><strong>Total</strong></td><td><strong>52</strong></td><td><strong>5</strong></td><td><strong>47</strong></td></tr></tbody></table><p>Only five of the 52 items can be judged from Azure data: public network access, private endpoints and managed identity on Azure Data Factory, and public network access and managed virtual network on Azure Synapse. Each runs only when the estate has those resources. Fabric capacities, Purview accounts, Databricks workspaces, reservations and AI accounts are attached to some questions as evidence only. Scout does not read Fabric tenant settings, workspaces, OneLake security, lineage or Purview content, because none is an Azure Resource Manager resource.</p>',31)])])}const m=e(n,[["render",o]]);export{p as __pageData,m as default};
